fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let colw: i32 = w / 12;
    let rest: i32 = (h - 120) * 8;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, (w / 2 - 80) * 8);
        host::display::state_set(3, 80 * 8);
        host::display::state_set(4, 14);
        host::display::state_set(5, 0);
    }
    let mut off = [0; 12];
    let mut vel = [0; 12];
    let mut i: i32 = 0;
    while i < 12 {
        off[i] = host::display::state_get(8 + i);
        vel[i] = host::display::state_get(20 + i);
        i = i + 1;
    }
    i = 0;
    while i < 12 {
        let left: i32 = if i > 0 { off[i - 1] } else { 0 };
        let right: i32 = if i < 11 { off[i + 1] } else { 0 };
        vel[i] = vel[i] + (left + right - 2 * off[i]) / 6 - off[i] / 16;
        i = i + 1;
    }
    let mut bx: i32 = host::display::state_get(2);
    let mut by: i32 = host::display::state_get(3);
    let mut bvx: i32 = host::display::state_get(4);
    let mut bvy: i32 = host::display::state_get(5);
    bvy = bvy + 3;
    bx = bx + bvx;
    by = by + bvy;
    if bx < 10 * 8 { bx = 10 * 8; bvx = -bvx; }
    if bx > (w - 10) * 8 { bx = (w - 10) * 8; bvx = -bvx; }
    if by < 10 * 8 { by = 10 * 8; bvy = 0 - bvy; }
    let mut col: i32 = (bx / 8) / colw;
    if col < 0 { col = 0; }
    if col > 11 { col = 11; }
    let surf: i32 = rest + off[col];
    if by + 80 > surf {
        by = surf - 80;
        if bvy > 0 {
            vel[col] = vel[col] + bvy / 2;
            bvy = 0 - (bvy * 3 / 4) - 15;
        }
    }
    i = 0;
    while i < 12 {
        vel[i] = vel[i] * 15 / 16;
        off[i] = off[i] + vel[i];
        if off[i] > 480 { off[i] = 480; }
        if off[i] < -480 { off[i] = -480; }
        host::display::state_set(8 + i, off[i]);
        host::display::state_set(20 + i, vel[i]);
        i = i + 1;
    }
    host::display::state_set(2, bx);
    host::display::state_set(3, by);
    host::display::state_set(4, bvx);
    host::display::state_set(5, bvy);
    host::display::clear(0x0e1014);
    i = 0;
    while i < 12 {
        let top: i32 = (rest + off[i]) / 8;
        host::display::fill_rect(i * colw, top, colw - 1, h - top, 0x203828);
        host::display::fill_rect(i * colw, top, colw - 1, 3, 0x50a068);
        i = i + 1;
    }
    host::display::fill_rect(bx / 8 - 10, by / 8 - 10, 20, 20, 0xff9030);
    host::display::draw_string(8, 8, "TRAMPOLINE MESH", 0x606060, 1);
    host::display::present();
}
